@@ -0,0 +1,5 @@
+{
+  "pr": 4097,
+  "date": "2026-07-26",
+  "reason": "[SONNET-4.6] #4097 intentionally changes always-compiled sparq-substrate numeric code used by sparq-engine: xsd:float lexicals and mixed Float arithmetic now convert integer/decimal operands directly to f32 instead of rounding through f64 first. Because the default feature-OFF sparq-wasm bundle consumes sparq-engine with sparq-substrate's numeric feature enabled, this correctness fix is expected to move its generated wasm bytes. This is not leakage from the default-OFF vectorized feature; the separate wasm bundle-size ratchet continues to govern the accepted size."
+}

@@ -21,7 +21,10 @@
 //! EXACT lexical path — `Dec::parse_lexical` (scale-preserving) for `xsd:decimal` and
 //! `parse_xsd_f32` / `parse_xsd_f64` (which handle the XSD `INF` / `-INF` / `NaN` /
 //! exponent spellings) for `xsd:float` / `xsd:double` — so classification is bit-identical
-//! to what the engine did before the move.
+//! to what the engine did before the move. [SONNET-4.6] The `xsd:float` value conversion
+//! now deliberately rounds the lexical directly to `f32`; unlike the pre-move
+//! `f64`-then-narrow path, this avoids double rounding while retaining the same lexical
+//! acceptance set as `xsd:double`.
 //!
 //! # Zero-overhead intent
 //!
@@ -378,6 +381,21 @@ impl Num {
         }
     }

+    /// [SONNET-4.6] The value promoted directly to `f32`, without an intermediate `f64`
+    /// rounding.
+    #[inline]
+    fn promoted_f32(self) -> f32 {
+        match self {
+            Num::Int(i) => i as f32,
+            Num::Dec(d) => d
+                .lexical()
+                .parse::<f32>()
+                .expect("a Dec lexical is always a valid f32 lexical"),
+            Num::Float(f) => f,
+            Num::Double(d) => d as f32,
+        }
+    }
+
     /// As an exact [`Dec`] for the exact tiers (`Int` / `Dec`); `None` for `Float` /
     /// `Double` (which are not exactly representable as a fixed-point decimal).
     #[inline]
@@ -470,7 +488,7 @@ impl Num {
             return Some(Num::Double(apply_f64(self.f64(), o.f64(), op)));
         }
         if rank == 2 {
-            let (a, b) = (self.f64() as f32, o.f64() as f32);
+            let (a, b) = (self.promoted_f32(), o.promoted_f32());
             return Some(Num::Float(apply_f64(a as f64, b as f64, op) as f32));
         }
         // Exact tier: integer / decimal.
@@ -770,10 +788,20 @@ pub fn parse_xsd_f64(v: &str) -> Option<f64> {
     sparq_core::parse_xsd_f64(v)
 }

-/// Parse an xsd:float lexical (the [`parse_xsd_f64`] spellings, narrowed to `f32`).
+/// [SONNET-4.6] Parse an xsd:float lexical directly at `f32` precision, avoiding the
+/// pre-move `f64`-then-narrow double-rounding path while retaining the XSD double lexical
+/// acceptance set.
 #[inline]
 pub fn parse_xsd_f32(v: &str) -> Option<f32> {
-    parse_xsd_f64(v).map(|d| d as f32)
+    match v {
+        "NaN" => Some(f32::NAN),
+        "INF" | "+INF" => Some(f32::INFINITY),
+        "-INF" => Some(f32::NEG_INFINITY),
+        _ if v.bytes().all(|c| c.is_ascii_digit() || matches!(c, b'+' | b'-' | b'.' | b'e' | b'E')) => {
+            v.parse::<f32>().ok()
+        }
+        _ => None,
+    }
 }

 /// Float/double serialisation: an INTEGRAL value prints as a plain integer ("6",
@@ -865,6 +893,23 @@ mod tests {
         assert!(matches!(as_numeric(&typed("1.5", xsd::FLOAT)), Some(Num::Float(f)) if f == 1.5));
     }

+    #[test]
+    fn float_promotion_and_parse_are_single_rounded() {
+        // [SONNET-4.6] This integer is a double-rounding witness: converting through
+        // f64 produces 0x5e800000, while direct correctly-rounded f32 conversion produces
+        // the adjacent value 0x5e800001.
+        const WITNESS: i64 = 4_611_686_293_305_294_849;
+        const CORRECT_BITS: u32 = 0x5e80_0001;
+
+        let promoted = Num::Int(WITNESS)
+            .binop(Num::Float(0.0), ArithOp::Add)
+            .expect("mixed integer/float addition is defined");
+        assert!(matches!(promoted, Num::Float(f) if f.to_bits() == CORRECT_BITS));
+
+        let parsed = parse_xsd_f32("4611686293305294849").expect("valid xsd:float lexical");
+        assert_eq!(parsed.to_bits(), CORRECT_BITS);
+    }
+
     #[test]
     fn language_tagged_and_non_numeric_are_not_numeric() {
         assert!(as_numeric(&Literal::new_language_tagged_literal("12", "en").unwrap()).is_none());
@@ -1024,6 +1069,22 @@ mod tests {
         assert_eq!(parse_xsd_f32("INF"), Some(f32::INFINITY));
         assert_eq!(parse_xsd_f32("-INF"), Some(f32::NEG_INFINITY));
         assert!(parse_xsd_f32("nan").is_none());
+
+        // [SONNET-4.6] Anti-drift regression for sq-9781x: f32 and f64 deliberately
+        // produce values at different precisions, but their lexical acceptance sets must
+        // remain identical so the numeric cache and evaluator cannot diverge again.
+        for lexical in [
+            "NaN", "INF", "+INF", "-INF", "6", "+1", "1.5E2", "-0.0", "1.", ".5", "inf",
+            "+inf", "-inf", "infinity", "-infinity", "Infinity", "nan", "NAN", "", "abc",
+            "1_000", "0x1p4", " 1", "1 ", "1e", ".", "+",
+        ] {
+            assert_eq!(
+                parse_xsd_f32(lexical).is_some(),
+                parse_xsd_f64(lexical).is_some(),
+                "sq-9781x: xsd:float and xsd:double lexical acceptance drifted for {:?}",
+                lexical
+            );
+        }
     }

     #[test]
